from collections import deque

def fixed_window_sums(nums, k):
    window, total, result = deque(), 0, []
    for value in nums:
        window.append(value)
        total += value
        if len(window) > k:
            total -= window.popleft()
        if len(window) == k:
            result.append(total)
    return result

